import inspect
import sys
from collections.abc import Callable, Iterable
from pathlib import Path

from dotlife.categories import CATEGORIES
from dotlife.schema import Aggregate, Category, Field, Grain, Kind, Metric

START_MARKER = (
    "<!-- categories:start (generated by `make docs`; don't edit by hand) -->"
)
END_MARKER = "<!-- categories:end -->"
FORMAT_DOC = Path(__file__).resolve().parent.parent / "FORMAT.md"

GRAINS = {
    Grain.DAY: "one row per day",
    Grain.SESSION: "one row per session",
    Grain.TRANSACTION: "one row per transaction",
    Grain.EVENT: "one row per event",
    Grain.ENTRY: "one text file per year, many entries a day",
}
KINDS = {
    Kind.DATE: "date",
    Kind.TIMESTAMP: "timestamp",
    Kind.LOCAL_TIME: "local time",
    Kind.TEXT: "text",
}
SUMMARIES = {
    Aggregate.SUM: "total",
    Aggregate.MEAN: "average",
    Aggregate.LAST: "latest",
    Aggregate.DAYS: "days above 0",
}
DIRECTIONS = {True: "higher", False: "lower", None: ""}


def number(value: float) -> str:
    """Format a number with thousands separators and no trailing ``.0``.

    Args:
        value: The number.

    Returns:
        E.g. ``60,000`` or ``-3``.
    """
    return f"{value:,g}"


def limits(metric: Metric) -> str:
    """Describe a metric's hard limits.

    Args:
        metric: The metric.

    Returns:
        E.g. ``0 to 1,440``, ``at least 0``, or empty when there are none.
    """
    low, high = metric.minimum, metric.maximum
    if low is not None and high is not None:
        return f"{number(low)} to {number(high)}"
    if low is not None:
        return f"at least {number(low)}"
    if high is not None:
        return f"at most {number(high)}"
    return ""


def plausible(metric: Metric) -> str:
    """Describe a metric's default plausible bounds.

    Args:
        metric: The metric.

    Returns:
        E.g. ``0 to 60,000``, or empty when it has none.
    """
    if metric.plausible is None:
        return ""
    low, high = metric.plausible
    return f"{number(low)} to {number(high)}"


def field_row(field: Field) -> str:
    """Render a table row for a non-numeric column.

    Args:
        field: The column.

    Returns:
        A Markdown table row.
    """
    required = "yes" if field.required else "no"
    return f"| `{field.name}` | {KINDS[field.kind]} | | {required} | | | | |"


def metric_row(metric: Metric) -> str:
    """Render a table row for a numeric column.

    Args:
        metric: The column.

    Returns:
        A Markdown table row.
    """
    return (
        f"| `{metric.column}` | number | {metric.unit} | no | {limits(metric)} "
        f"| {plausible(metric)} | {SUMMARIES[metric.aggregate]} "
        f"| {DIRECTIONS[metric.higher_is_better]} |"
    )


def summary_line(function: Callable) -> str:
    """Return the first line of a plug-in's docstring, which states its rule.

    Args:
        function: A check or day filter.

    Returns:
        The rule in one sentence, with reStructuredText code marks made Markdown.
    """
    first_line = (inspect.getdoc(function) or function.__name__).splitlines()[0]
    return first_line.replace("``", "`")


def category_section(category: Category) -> str:
    """Render one category's part of FORMAT.md.

    Args:
        category: The category.

    Returns:
        Markdown: a heading, where the data lives, a column table, and its rules.
    """
    facts = [f"`{category.file}`", GRAINS[category.grain]]
    if category.key:
        facts.append(f"unique: {', '.join(f'`{name}`' for name in category.key)}")
    if category.expect_every_day:
        facts.append("expected every day (gaps are reported)")
    if category.sensitive:
        facts.append("sensitive")
    lines = [
        f"### {category.label}",
        "",
        f"Config section `[{category.name}]`. " + ", ".join(facts) + ".",
        "",
        "| Column | Type | Unit | Required | Limits | Plausible | Summary | Better |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
        *(field_row(field) for field in category.fields),
        *(metric_row(metric) for metric in category.metrics),
    ]
    related = [
        f"`{metric.column}` is flagged as stuck if it stays flat while "
        + " or ".join(f"`{name}`" for name in metric.related)
        + " moves."
        for metric in category.metrics
        if metric.related
    ]
    rules = [
        summary_line(check) for check in (*category.checks, *category.warnings)
    ] + related
    if category.day_filter is not None:
        rules.append(summary_line(category.day_filter))
    if rules:
        lines += ["", *(f"- {rule}" for rule in rules)]
    return "\n".join(lines)


def render_categories(categories: Iterable[Category]) -> str:
    """Render every category's section.

    Args:
        categories: The categories, in the order they should appear.

    Returns:
        The Markdown that goes between the markers in FORMAT.md.
    """
    return "\n\n".join(category_section(category) for category in categories)


def replace_generated(document: str, generated: str) -> str:
    """Replace the text between the markers of a document.

    Args:
        document: The whole document.
        generated: The new text for between the markers.

    Returns:
        The document with the generated part replaced.

    Raises:
        ValueError: If either marker is missing or they're out of order.
    """
    start = document.find(START_MARKER)
    end = document.find(END_MARKER)
    if start == -1 or end < start:
        raise ValueError(
            f"FORMAT.md needs the markers {START_MARKER!r} and then {END_MARKER!r}"
        )
    head = document[: start + len(START_MARKER)]
    return f"{head}\n\n{generated}\n\n{document[end:]}"


def updated_format_doc(path: Path = FORMAT_DOC) -> str:
    """Return FORMAT.md as it should be, with freshly generated category tables.

    Args:
        path: Path to FORMAT.md.

    Returns:
        The updated document.

    Raises:
        ValueError: If the file lacks the markers.
    """
    with path.open(encoding="utf-8") as file:
        document = file.read()
    return replace_generated(document, render_categories(CATEGORIES))


def main() -> int:
    """Rewrite FORMAT.md's generated part in place.

    Returns:
        The process exit code.
    """
    document = updated_format_doc()
    with FORMAT_DOC.open("w", encoding="utf-8") as file:
        file.write(document)
    return 0


if __name__ == "__main__":
    sys.exit(main())
